def test_import_certificate(page):
    # Base64 encoded P12 from previous step
    p12_base64 = ""

    page.goto("http://127.0.0.1/overview")
    page.wait_for_url("**/overview")

    page.locator("table tbody tr").first.wait_for(state="visible")
    initial_cert_count = count_table_data_rows(page)
    
    page.click("#ImportCertificateButton")
    page.fill("#importP12", p12_base64)
    page.fill("#importPassword", "testpassword")
    page.select_option("#importFormat", "der")
    page.select_option("#importUserId", "1")
    # ca_id 1 should already exist from setup
    page.select_option("#importCaId", "1")
    page.select_option("#importCertType", "0")  # TLSClient
    page.get_by_test_id("import-certificate-button").click()
    
    page.wait_for_timeout(2000)
    assert count_table_data_rows(page) == initial_cert_count + 1
    assert "E2E Imported User Cert" in page.locator(".active-certs tbody tr").last.inner_text()
